operations.replace:
ensureTurnPlan() {
  return ensureTurnPlan(
    this
  );
}


beginTurnPlan() {
  return beginTurnPlan(
    this
  );
}

const categoryId =
  event.currentTarget
    .dataset
    .frameHelmCategory ??
  null;


const beginsTurnPlan =
  categoryId ===
    "movement" ||
  categoryId ===
    "quick" ||
  categoryId ===
    "full" ||
  categoryId ===
    "special" ||
  categoryId ===
    "protocol";


if (
  beginsTurnPlan &&
  !application.ensureTurnPlan()
) {
  return;
}


application.selectedCategory =
  categoryId;


application.render(
  false
);
